/// <summary>
/// N.Freidenberger 27.02.2024
/// </summary>
/// <param name = "_JournalTrans"_JournalTrans></param>
public void initFromJournalTrans(KCS_BOSJournalTrans _JournalTrans)
{

    next initFromJournalTrans(_JournalTrans);
    if (_JournalTrans is KCS_BOSJournalTrans_C)
    {
        KCS_BOSJournalTrans_C    journalTrans_C = _JournalTrans as KCS_BOSJournalTrans_C;
        this.BonusDeductedAmount =   journalTrans_C.BonusDeductedAmount;
        this.InvoiceAmount       =   journalTrans_C.InvoiceAmount;
    }
}

/// <summary>
///     AVA <c>findRecId</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
/// <param name="_recId">
///     <c>RecId</c> as type
/// </param>
/// <param name="_forUpdate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>KCS_BOSTrans_C</c> as return value
/// </returns>
public static KCS_BOSTrans_C findRecId( RecId   _recId, 
                                        boolean _forUpdate = false)
{
    KCS_BOSTrans_C      locKCS_BOSTrans_C;

    locKCS_BOSTrans_C.selectForUpdate(_forUpdate);

    select firstOnly locKCS_BOSTrans_C
    where locKCS_BOSTrans_C.RecId == _recId;

    return locKCS_BOSTrans_C;
}
